/// <summary>A player joins its race with the token from the match start (sent until Joined).</summary>
public sealed record Join(ulong Token) : RelayPacket(PacketType.Join);

/// <summary>The player's seat and the race's player seats (bit i = seat i); the cookie of the address the Join came from, which every later packet of the game carries (so that the relay sends the race only to an address that proved it receives there); Flags (JoinedFlags); the frames closed so far.</summary>
