/// <summary>Every player is ready: frame 0 starts now. StartBarrier: the race-start barrier's frame (the relay's ServerOptions.StartBarrierFrame), from which the game's catch-up counts.</summary>
public sealed record Go(uint Session, uint StartBarrier, ulong Key = 0) : RelayPacket(PacketType.Go);

